/// to conditionally assign the document menu item.
/// </summary>
[ExtensionOf(tableStr(WorkflowWorkItemTable))]
final class METWorkflowWorkItemTable_Extension
{
}

Method.Source:
/// <summary>
/// Retrieves the user who submitted the invoice to workflow.
/// </summary>
/// <returns>
/// A string that contains the user who submitted the invoice to workflow.
/// </returns>
[SysClientCacheDataMethod(true)]
public display NetworkAlias getUserEMailAddress()
{
    UserInfo    userInfo;

    if (this.UserId)
    {
        select firstonly networkAlias from userInfo
            where userInfo.Id == this.UserId;
    }

    return (userInfo.networkAlias) ? userInfo.networkAlias : '';
}
